Here's a JWT authentication middleware:

```javascript
// middleware/auth.js
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

module.exports = { authenticate };
```

Apply it to protected routes:

```javascript
router.get('/profile', authenticate, getProfile);
router.put('/:id', authenticate, updateUser);
```

Use a centralized error handling middleware in Express:

```javascript
// middleware/errorHandler.js
const errorHandler = (err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  res.status(status).json({
    error: {
      message,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    }
  });
};

module.exports = errorHandler;
```

In your routes, pass errors to next:

```javascript
router.get('/:id', async (req, res, next) => {
  try {
    const user = await User.findById(req.params.id);
    if (!user) throw Object.assign(new Error('User not found'), { status: 404 });
    res.json(user);
  } catch (err) {
    next(err);
  }
});
```

Register the error handler LAST in app.js: `app.use(errorHandler);`
